-- Required world totem-source restoration, staged disabled until whole install.
-- Original spawn2 positions/grids/timers preserved. Approximate rare weight and
-- missing Maleko combat/drop values are labelled in data/totem-restoration.json.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_tbs_totem_old`;CREATE TEMPORARY TABLE `_tbs_totem_old` LIKE spawnentry;
DROP TEMPORARY TABLE IF EXISTS `_tbs_totem_new`;CREATE TEMPORARY TABLE `_tbs_totem_new` LIKE spawnentry;
DROP TEMPORARY TABLE IF EXISTS `_tbs_maleko`;CREATE TEMPORARY TABLE `_tbs_maleko` LIKE npc_types;
DROP TEMPORARY TABLE IF EXISTS `_tbs_totem_positions`;CREATE TEMPORARY TABLE `_tbs_totem_positions`(id INT PRIMARY KEY,group_id INT,x FLOAT,y FLOAT,z FLOAT,heading FLOAT,pathgrid INT,respawntime INT);
START TRANSACTION;
SELECT s.id FROM spawn2 s JOIN `_tbs_totem_positions` p ON p.group_id=s.spawngroupID FOR UPDATE;
SELECT a.spawngroupID FROM spawnentry a JOIN `_tbs_totem_positions` p ON p.group_id=a.spawngroupID FOR UPDATE;
SELECT id FROM npc_types WHERE id IN(423061,423901) FOR UPDATE;
SET @tbs_totem_ok=IF(COALESCE(@buriedsea_whole_batch_reviewed,0)=1
 AND(SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN('spawnentry','spawn2','npc_types') AND ENGINE='InnoDB')=3
 AND(SELECT COUNT(*) FROM items WHERE id IN(54747,54748))=2
 AND NOT EXISTS(SELECT 1 FROM `_tbs_totem_new` e LEFT JOIN npc_types n ON n.id=e.npcID WHERE e.npcID<>423901 AND n.id IS NULL)
 AND(SELECT COUNT(*) FROM npc_types WHERE id=423061 AND name='#Lutzan,_the_Magma_Reaver')=1
 AND NOT EXISTS(SELECT 1 FROM npc_types a JOIN `_tbs_maleko` e ON a.id=e.id WHERE NOT(a.`id`<=>e.`id` AND a.`name`<=>e.`name` AND a.`lastname`<=>e.`lastname` AND a.`level`<=>e.`level` AND a.`race`<=>e.`race` AND a.`class`<=>e.`class` AND a.`bodytype`<=>e.`bodytype` AND a.`hp`<=>e.`hp` AND a.`mana`<=>e.`mana` AND a.`gender`<=>e.`gender` AND a.`texture`<=>e.`texture` AND a.`helmtexture`<=>e.`helmtexture` AND a.`herosforgemodel`<=>e.`herosforgemodel` AND a.`size`<=>e.`size` AND a.`hp_regen_rate`<=>e.`hp_regen_rate` AND a.`hp_regen_per_second`<=>e.`hp_regen_per_second` AND a.`mana_regen_rate`<=>e.`mana_regen_rate` AND a.`loottable_id`<=>e.`loottable_id` AND a.`merchant_id`<=>e.`merchant_id` AND a.`greed`<=>e.`greed` AND a.`alt_currency_id`<=>e.`alt_currency_id` AND a.`npc_spells_id`<=>e.`npc_spells_id` AND a.`npc_spells_effects_id`<=>e.`npc_spells_effects_id` AND a.`npc_faction_id`<=>e.`npc_faction_id` AND a.`adventure_template_id`<=>e.`adventure_template_id` AND a.`trap_template`<=>e.`trap_template` AND a.`mindmg`<=>e.`mindmg` AND a.`maxdmg`<=>e.`maxdmg` AND a.`attack_count`<=>e.`attack_count` AND a.`npcspecialattks`<=>e.`npcspecialattks` AND a.`special_abilities`<=>e.`special_abilities` AND a.`aggroradius`<=>e.`aggroradius` AND a.`assistradius`<=>e.`assistradius` AND a.`face`<=>e.`face` AND a.`luclin_hairstyle`<=>e.`luclin_hairstyle` AND a.`luclin_haircolor`<=>e.`luclin_haircolor` AND a.`luclin_eyecolor`<=>e.`luclin_eyecolor` AND a.`luclin_eyecolor2`<=>e.`luclin_eyecolor2` AND a.`luclin_beardcolor`<=>e.`luclin_beardcolor` AND a.`luclin_beard`<=>e.`luclin_beard` AND a.`drakkin_heritage`<=>e.`drakkin_heritage` AND a.`drakkin_tattoo`<=>e.`drakkin_tattoo` AND a.`drakkin_details`<=>e.`drakkin_details` AND a.`armortint_id`<=>e.`armortint_id` AND a.`armortint_red`<=>e.`armortint_red` AND a.`armortint_green`<=>e.`armortint_green` AND a.`armortint_blue`<=>e.`armortint_blue` AND a.`d_melee_texture1`<=>e.`d_melee_texture1` AND a.`d_melee_texture2`<=>e.`d_melee_texture2` AND a.`ammo_idfile`<=>e.`ammo_idfile` AND a.`prim_melee_type`<=>e.`prim_melee_type` AND a.`sec_melee_type`<=>e.`sec_melee_type` AND a.`ranged_type`<=>e.`ranged_type` AND a.`runspeed`<=>e.`runspeed` AND a.`MR`<=>e.`MR` AND a.`CR`<=>e.`CR` AND a.`DR`<=>e.`DR` AND a.`FR`<=>e.`FR` AND a.`PR`<=>e.`PR` AND a.`Corrup`<=>e.`Corrup` AND a.`PhR`<=>e.`PhR` AND a.`see_invis`<=>e.`see_invis` AND a.`see_invis_undead`<=>e.`see_invis_undead` AND a.`qglobal`<=>e.`qglobal` AND a.`AC`<=>e.`AC` AND a.`npc_aggro`<=>e.`npc_aggro` AND a.`spawn_limit`<=>e.`spawn_limit` AND a.`attack_speed`<=>e.`attack_speed` AND a.`attack_delay`<=>e.`attack_delay` AND a.`findable`<=>e.`findable` AND a.`STR`<=>e.`STR` AND a.`STA`<=>e.`STA` AND a.`DEX`<=>e.`DEX` AND a.`AGI`<=>e.`AGI` AND a.`_INT`<=>e.`_INT` AND a.`WIS`<=>e.`WIS` AND a.`CHA`<=>e.`CHA` AND a.`see_hide`<=>e.`see_hide` AND a.`see_improved_hide`<=>e.`see_improved_hide` AND a.`trackable`<=>e.`trackable` AND a.`isbot`<=>e.`isbot` AND a.`exclude`<=>e.`exclude` AND a.`ATK`<=>e.`ATK` AND a.`Accuracy`<=>e.`Accuracy` AND a.`Avoidance`<=>e.`Avoidance` AND a.`slow_mitigation`<=>e.`slow_mitigation` AND a.`version`<=>e.`version` AND a.`maxlevel`<=>e.`maxlevel` AND a.`scalerate`<=>e.`scalerate` AND a.`private_corpse`<=>e.`private_corpse` AND a.`unique_spawn_by_name`<=>e.`unique_spawn_by_name` AND a.`underwater`<=>e.`underwater` AND a.`isquest`<=>e.`isquest` AND a.`emoteid`<=>e.`emoteid` AND a.`spellscale`<=>e.`spellscale` AND a.`healscale`<=>e.`healscale` AND a.`no_target_hotkey`<=>e.`no_target_hotkey` AND a.`raid_target`<=>e.`raid_target` AND a.`armtexture`<=>e.`armtexture` AND a.`bracertexture`<=>e.`bracertexture` AND a.`handtexture`<=>e.`handtexture` AND a.`legtexture`<=>e.`legtexture` AND a.`feettexture`<=>e.`feettexture` AND a.`light`<=>e.`light` AND a.`walkspeed`<=>e.`walkspeed` AND a.`peqid`<=>e.`peqid` AND a.`unique_`<=>e.`unique_` AND a.`fixed`<=>e.`fixed` AND a.`ignore_despawn`<=>e.`ignore_despawn` AND a.`show_name`<=>e.`show_name` AND a.`untargetable`<=>e.`untargetable` AND a.`charm_ac`<=>e.`charm_ac` AND a.`charm_min_dmg`<=>e.`charm_min_dmg` AND a.`charm_max_dmg`<=>e.`charm_max_dmg` AND a.`charm_attack_delay`<=>e.`charm_attack_delay` AND a.`charm_accuracy_rating`<=>e.`charm_accuracy_rating` AND a.`charm_avoidance_rating`<=>e.`charm_avoidance_rating` AND a.`charm_atk`<=>e.`charm_atk` AND a.`skip_global_loot`<=>e.`skip_global_loot` AND a.`rare_spawn`<=>e.`rare_spawn` AND a.`stuck_behavior`<=>e.`stuck_behavior` AND a.`model`<=>e.`model` AND a.`flymode`<=>e.`flymode` AND a.`always_aggro`<=>e.`always_aggro` AND a.`exp_mod`<=>e.`exp_mod` AND a.`heroic_strikethrough`<=>e.`heroic_strikethrough` AND a.`faction_amount`<=>e.`faction_amount` AND a.`keeps_sold_items`<=>e.`keeps_sold_items` AND a.`is_parcel_merchant`<=>e.`is_parcel_merchant` AND a.`multiquest_enabled`<=>e.`multiquest_enabled` AND a.`npc_tint_id`<=>e.`npc_tint_id`))
 AND(SELECT COUNT(*) FROM spawn2 s JOIN `_tbs_totem_positions` p ON s.id=p.id AND s.spawngroupID=p.group_id AND s.zone='buriedsea'
  AND s.x=p.x AND s.y=p.y AND s.z=p.z AND s.heading=p.heading AND s.pathgrid=p.pathgrid AND s.respawntime=p.respawntime)=68
 AND NOT EXISTS(SELECT 1 FROM spawn2 s JOIN `_tbs_totem_positions` p ON s.spawngroupID=p.group_id WHERE s.id<>p.id)
 AND NOT EXISTS(SELECT 1 FROM `_tbs_totem_positions` p WHERE NOT(
 ((SELECT COUNT(*) FROM spawnentry a WHERE a.spawngroupID=p.group_id)=1
  AND(SELECT COUNT(*) FROM spawnentry a JOIN `_tbs_totem_old` o ON a.spawngroupID=o.spawngroupID AND a.npcID=o.npcID WHERE a.spawngroupID=p.group_id AND a.`spawngroupID`<=>o.`spawngroupID` AND a.`npcID`<=>o.`npcID` AND a.`chance`<=>o.`chance` AND a.`condition_value_filter`<=>o.`condition_value_filter` AND a.`min_time`<=>o.`min_time` AND a.`max_time`<=>o.`max_time` AND a.`min_expansion`<=>o.`min_expansion` AND a.`max_expansion`<=>o.`max_expansion` AND a.`content_flags`<=>o.`content_flags` AND a.`content_flags_disabled`<=>o.`content_flags_disabled`)=1)
 OR((SELECT COUNT(*) FROM spawnentry a WHERE a.spawngroupID=p.group_id)=2
  AND(SELECT COUNT(*) FROM spawnentry a JOIN `_tbs_totem_new` n ON a.spawngroupID=n.spawngroupID AND a.npcID=n.npcID WHERE a.spawngroupID=p.group_id AND a.`spawngroupID`<=>n.`spawngroupID` AND a.`npcID`<=>n.`npcID` AND a.`chance`<=>n.`chance` AND a.`condition_value_filter`<=>n.`condition_value_filter` AND a.`min_time`<=>n.`min_time` AND a.`max_time`<=>n.`max_time` AND a.`min_expansion`<=>n.`min_expansion` AND a.`max_expansion`<=>n.`max_expansion` AND a.`content_flags`<=>n.`content_flags` AND a.`content_flags_disabled`<=>n.`content_flags_disabled`)=2))),1,0);
DROP TEMPORARY TABLE IF EXISTS `_tbs_totem_guard`;CREATE TEMPORARY TABLE `_tbs_totem_guard`(ok INT NOT NULL CHECK(ok=1));
DELETE a FROM spawnentry a JOIN `_tbs_totem_positions` p ON a.spawngroupID=p.group_id WHERE @tbs_totem_ok=1;
COMMIT;
